mapper.select:
SELECT s.id AS id, s.plan_id AS planId, t.task_name AS taskName, t.task_cron AS taskCron, t.remark AS remark, t.task_type AS taskType, t.url AS url, t.exe_path AS exePath, t.depend_id AS dependId, t.username AS username, t.password AS password, t.driver AS driver, t.task_system AS taskSystem, t.theme AS theme, t.period AS period, t.job_key AS jobKey, s.data_date AS dataDate, s.status AS status, s.begin_time AS beginTime, s.update_time AS updateTime, s.end_time AS endTime, s.msg AS msg, CASE WHEN s.status = '3' OR s.status = '4' THEN 'true' ELSE 'false' END AS _disabled, s.create_time AS createTime FROM t_quartz_task_status s INNER JOIN t_quartz_task t ON s.plan_id = t.id WHERE 1 = 1
AND s.create_date = #{queryDTO.beginDate}
AND s.data_date = #{queryDTO.dataDate}
AND t.id = #{queryDTO.id}
AND INSTR(t.task_name, #{queryDTO.taskName})
AND INSTR(t.task_system, #{queryDTO.taskSystem})
AND INSTR(t.theme, #{queryDTO.theme})
AND s.status = #{queryDTO.status}
ORDER BY s.update_time DESC

SELECT status
FROM t_quartz_task_status
WHERE plan_id = #{planId}
  AND data_date = #{dataDate}
LIMIT 1

